#!/usr/bin/env bash
# =============================================================================
# Instantgram v1.7.0  -  Music, volume control, inline clips, thinner navigation
#   * Clips: hold and slide up / down = volume (hold without sliding = 2x speed).
#   * Share / copy link sends the link only.
#   * Moments open fast (smaller pictures, loaded in advance, timer starts after loading).
#   * Discover: centred "InstantGram" title, no profile button; clips play inside the feed;
#     "View all comments" removed; much thinner bottom navigation.
#   * Create: music from the InstantGram library only (no import); photo clips with music
#     (5 to 30 seconds).
# Run from the project root:   bash update_v170_music_inline.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="b22366c213bd541e7fdf7cc9f7924d11668e27bc16afc9dc9a2f596d4ea52f42"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/screens/profile/edit_profile_screen.dart ] || { echo "ERROR: v1.6.0 is not installed. Run update_v160_clips_profile.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')
echo "    Dart package: $APP_NAME"

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
awk '/^__PAYLOAD__$/{f=1;next} f' "$0" | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       Download it again and retry."
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the updated files and the music..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
sed -i "s#package:instantgram/#package:${APP_NAME}/#" lib/core/share.dart test/*.dart 2>/dev/null || true
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

echo "==> Registering the music folder in pubspec.yaml..."
python3 - <<'PYEOF'
import re
p = 'pubspec.yaml'
s = open(p, encoding='utf-8').read()
if 'assets/music/' in s:
    print('    already registered')
else:
    lines = s.split('\n')
    done = False
    for i, ln in enumerate(lines):
        if re.match(r'^  assets:\s*$', ln):
            lines.insert(i + 1, '    - assets/music/')
            done = True
            break
    if not done:
        for i, ln in enumerate(lines):
            if re.match(r'^  uses-material-design:', ln):
                lines[i + 1:i + 1] = ['', '  assets:', '    - assets/music/']
                done = True
                break
    if not done:
        for i, ln in enumerate(lines):
            if re.match(r'^flutter:\s*$', ln):
                lines[i + 1:i + 1] = ['  assets:', '    - assets/music/']
                done = True
                break
    if not done:
        raise SystemExit('ERROR: could not find the flutter: section in pubspec.yaml')
    open(p, 'w', encoding='utf-8').write('\n'.join(lines))
    print('    added assets/music/')
PYEOF

echo ""
echo "Done. v1.7.0 is in place."
echo ""
echo "Nothing to publish this time: Firestore rules and the signer are unchanged."
echo ""
echo "Next:"
echo "  flutter clean && flutter pub get && dart analyze && flutter test"
echo '  git add -A && git commit -m "v1.7.0: music, volume, inline clips, thin nav" && git push'
exit 0
